/* Types */
export type AppError = {
	/**  What failed, for logic: `e.is(ErrorCode::PortInUse)`. */
	code: ErrorCode,
	/**
	 *  The catalogue key of `message` (`errors.*`), which the frontend
	 *  renders with `params`; empty for text not in the catalogue.
	 */
	key: string,
	params: { [key in string]: Param },
	/**  In English, for the app log and when the key is unknown. */
	message: string,
	hint: Hint | null,
	/**  The raw cause, for the Details dialog. Never translated. */
	detail: string | null,
};

export type AppInfo = {
	name: string,
	version: string,
	os: string,
	arch: string,
};

export type AvailableUpdate = {
	version: string,
	/**  Markdown release notes. */
	notes: string | null,
	/**  RFC 3339 publication date. */
	date: string | null,
};

/**  An SSH server an SSH Host is reached through (`ProxyJump`, ADR 0012). */
export type Bastion = {
	host: string,
	port: number,
	user: string,
	auth: BastionAuth,
	/**  OpenSSH public key of an `imported` key, shown to the user. */
	publicKey: string | null,
	/**
	 *  The bastion's server key, trusted on first use. Kept by Homeport:
	 *  whatever the frontend sends here is replaced by the stored one.
	 */
	hostKey: string | null,
};

export type BastionAuth = 
/**  The Host's own key or agent. */
"sameAsHost" | 
/**  A private key of its own, sealed with the Host's secrets. */
"imported" | 
/**  Keys offered by the running ssh-agent. */
"agent";

/**
 *  The private key typed for the `imported` bastion at `index` in the input's
 *  list. A bastion with no entry keeps the key stored for its address.
 */
export type BastionKeyInput = {
	index: number,
	privateKey: string,
	passphrase: string | null,
};

export type BuildArg = {
	name: string,
	value: string,
};

export type BuildEvent = 
/**  A line of the build's output. */
{ type: "line"; text: string } | 
/**  The image was built and named. */
{ type: "done"; imageId: string | null; tags: string[] } | { type: "error"; error: AppError };

export type BuildSpec = {
	/**  The build context: a folder on this machine. */
	context: string,
	/**  Relative to the context; `Dockerfile` when empty. */
	dockerfile: string,
	buildArgs: BuildArg[],
	/**  The stage to stop at, for multi-stage Dockerfiles. */
	target: string | null,
	/**  `repo:tag` names for the result; the first is applied by the build. */
	tags: string[],
	noCache: boolean,
	/**  Pull newer versions of the `FROM` images even if the Host has them. */
	pull: boolean,
};

export type BundleChoice = {
	index: number,
	name: string,
};

/**  A Host in an export file, as the import preview shows it. */
export type BundleHost = {
	/**  Its place in the file, which the import refers to. */
	index: number,
	name: string,
	/**  `name`, or a free variant when a Host already has it. */
	suggestedName: string,
	nameTaken: boolean,
	connection: HostConnection,
	/**  It needs secrets but was exported without them. */
	secretsMissing: boolean,
};

/**  What this machine can do; features degrade gracefully when something is missing. */
export type Capabilities = {
	/**  An OS keychain is reachable, so SSH, TLS, stack `.env` and registry secrets can be stored. */
	keychain: boolean,
	/**  Whether Managed Stacks can be deployed here. */
	compose: ComposeSupport,
};

export type CommitSpec = {
	/**  The new image's name, `repo[:tag]`; an existing tag moves to it. */
	reference: string,
	/**  The commit message, shown in the image's history. */
	comment: string | null,
	author: string | null,
	/**  Pause the container while committing, so its files are consistent. */
	pause: boolean,
	/**  Dockerfile instructions applied to the image, one per entry, like `ENV MODE=prod`. */
	changes: string[],
};

export type ComposeAction = 
/**
 *  `up -d --remove-orphans`: deploy or redeploy, after pulling the
 *  images the Host lacks through the Engine API.
 */
"up" | 
/**  Pulls every service's image through the Engine API; compose isn't run. */
"pull" | 
/**  `down --remove-orphans`, keeping volumes. */
"down" | 
/**  `down -v --remove-orphans`: also deletes the Stack's volumes. */
"downWithVolumes";

export type ComposeCheck = {
	/**  Problems that block deploying. */
	errors: string[],
	/**  Things that will probably not do what the author expects. */
	warnings: string[],
};

/**  How to invoke Compose on this machine. */
export type ComposeCli = {
	program: string,
	/**  `["compose"]` for the Docker CLI plugin, empty for standalone `docker-compose`. */
	prefix: string[],
	version: string,
};

export type ComposeEvent = { type: "line"; text: string } | 
/**  `error` explains a failed exit, from the end of stderr. */
{ type: "exit"; success: boolean; code: number | null; error: AppError | null } | { type: "error"; error: AppError };

/**  The compose CLI used to deploy Managed Stacks, or why there's none. */
export type ComposeSupport = { state: "available"; cli: ComposeCli } | 
/**  `problem` says what's missing and how to install it. */
{ state: "unavailable"; problem: AppError };

export type Container = {
	id: string,
	name: string,
	image: string,
	imageId: string,
	command: string,
	/**  Unix time in seconds. */
	created: number,
	/**  `created`, `running`, `paused`, `restarting`, `exited`, `removing` or `dead`. */
	state: string,
	/**  Human status from the Engine, e.g. "Up 3 hours (healthy)". */
	status: string,
	health: string | null,
	ports: PortBinding[],
	labels: { [key in string]: string },
	stack: string | null,
	service: string | null,
	networks: string[],
};

export type ContainerAction = "start" | "stop" | "restart" | "pause" | "unpause" | "kill";

export type ContainerUsage = {
	id: string,
	cpuPercent: number | null,
	memoryUsage: number,
	memoryLimit: number,
};

/**  Credentials typed by the user. Absent on update means "keep the stored ones". */
export type CredentialsInput = { kind: "tls"; caPem: string; certPem: string; keyPem: string } | { kind: "sshKey"; privateKey: string; passphrase: string | null };

export type DetectedEngine = {
	/**  The product that usually owns this socket, e.g. "Colima". */
	label: string,
	socketPath: string,
	engineVersion: string,
};

/**  A device of the Host made available inside the container (`--device`). */
export type DeviceSpec = {
	/**  An absolute path under the Host's `/dev`. */
	hostPath: string,
	/**  Where it appears in the container; the same path when empty. */
	containerPath: string | null,
	/**  Some of `r`, `w` and `m`. */
	permissions: string,
};

export type DiskUsage = {
	images: UsageLine,
	containers: UsageLine,
	volumes: UsageLine,
	buildCache: UsageLine,
	/**
	 *  The Engine predates per-type disk usage (API 1.52, Docker 29), so the
	 *  numbers come from its lists: image sizes are approximate, and volume
	 *  and build cache sizes are unknown (0).
	 */
	partial: boolean,
};

/**  One entry of a Host's Engine event stream. */
export type EngineEvent = {
	/**  Unix time in seconds. */
	time: number,
	/**  `container`, `image`, `volume`, `network`, … */
	kind: string,
	action: string,
	actorId: string,
	attributes: { [key in string]: string },
};

export type EngineEventReceived = {
	hostId: string,
	event: EngineEvent,
};

export type EngineInfo = {
	name: string,
	serverVersion: string,
	operatingSystem: string,
	kernelVersion: string,
	architecture: string,
	cpus: number,
	memory: number,
	rootDir: string,
	storageDriver: string,
	containers: number,
	running: number,
	paused: number,
	stopped: number,
	images: number,
};

/**  Stable machine-readable identifier of a failure, one per case the user can act on. */
export type ErrorCode = 
/**  A failure that started in the frontend, outside any command. */
"unknown" | "io" | "json" | "db" | "db_locked" | "db_corrupt" | "db_migration" | "tauri" | "validation" | "not_found" | "keychain_unavailable" | "credentials_lost" | "update_network" | "update_signature_invalid" | "update_permission_denied" | "update_failed" | 
/**  An export file that the passphrase doesn't open, or that was damaged. */
"bundle_unreadable" | 
/**  An export file from a newer Homeport. */
"bundle_too_new" | "host_not_connected" | "engine_not_installed" | "engine_not_running" | "permission_denied" | "dns_failed" | "connection_refused" | "timeout" | "network_unreachable" | "connection_lost" | "tls_required" | "tls_not_supported" | "tls_certificate_expired" | "tls_certificate_not_yet_valid" | "tls_unknown_ca" | "tls_name_mismatch" | "tls_client_rejected" | "tls_handshake_failed" | "tls_material_invalid" | "ssh_auth_failed" | "ssh_agent_unavailable" | "ssh_key_invalid" | "ssh_failed" | "remote_engine_unavailable" | "host_key_untrusted" | "host_key_changed" | "engine_error" | "bad_request" | "forbidden" | "conflict" | "name_in_use" | "in_use" | "container_running" | "container_not_running" | "already_done" | "port_in_use" | "disk_full" | "image_not_found" | "registry_auth_required" | "registry_rate_limited" | "registry_unreachable" | "registry_login_failed" | "api_version_unsupported" | "build_failed" | 
/**  A GPU was requested from a Host without the vendor's container toolkit. */
"gpu_unavailable" | 
/**  Recreating a container failed, and so did putting the original back. */
"recreate_rolled_back" | "compose_missing" | "compose_outdated" | "compose_spawn_failed" | "compose_invalid_definition" | "compose_missing_variable" | "compose_failed" | 
/**  A Linked Stack's folder, or one of its compose files, is gone. */
"stack_folder_missing" | 
/**  A Linked Stack's compose file can't be read or written. */
"stack_file_unreadable" | 
/**  A Linked Stack's compose file changed on disk since it was opened. */
"stack_files_changed" | "no_shell" | "path_not_found" | "container_permission_denied" | "file_too_large";

